      { label: "here" },
      { who: "m1", text: "……嗯。" },
      { who: "m1", text: "你說的喔。" },
      { goto: "after" },
      { label: "remember" },
      { who: "m1", text: "好好記住……" },
      { text: "他睜開眼睛，看著辦公室裡吵吵鬧鬧的大家。" },
      { who: "m1", text: "嗯。我要記住。" },
      { label: "after" },
      { text: "突然，辦公室的燈「啪」地一聲全暗了。" },
      { who: "m6", text: "啊啊啊啊！" },
      { who: "m3", text: "停電了！大家不要慌！活動長在這裡！" },
      { who: "m2", text: "慌的人是你。" },
      { who: "m5", text: "燦榮你抓到我的手了。" },
      { who: "m6", text: "我以為那是元彬哥！" },
      { who: "m4", text: "我在這裡。" },
      { text: "黑暗裡，元彬打開了手機的手電筒。一道、兩道、三道……七道光亮起來。" },
      { text: "窗外，天空很乾淨。可以看到星星。" },
      { who: "m3", text: "……哇。" },
      { text: "大家都安靜了下來，擠到窗邊。" },
      { who: "m5", text: "原來學校看得到星星。" },
      { who: "m2", text: "一直都看得到。只是我們沒有抬頭。" },
      { text: "過了十分鐘，電來了。" },
      { text: "但沒有人急著回到自己的位置上。" },
      { text: "那天晚上，校慶的海報還是沒有畫完，預算還是沒有算完。" },
      { text: "但你覺得，好像有什麼東西，比那些都重要的，被好好地記下來了。" }
