    nightTime: "22:00",            // 星期日（能用手機的日子）晚上，手機上的時間從這裡開始走
    alarm: { time: "7:00", label: "鬧鐘", snooze: "稍後提醒", stop: "滑動來停止", snoozeMs: 4000 }
